python3 -c "
import zipfile, re, xml.etree.ElementTree as ET
z = zipfile.ZipFile('budget.xlsx')
wb = ET.fromstring(z.read('xl/workbook.xml'))
ns = {'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main','r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
relmap = {r.get('Id'): r.get('Target') for r in rels}
for sh in wb.find('m:sheets', ns):
    rid = sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
    print('SHEET:', sh.get('name'), '->', relmap.get(rid))
sheet = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
for row in sheet.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
    vals = []
    for c in row:
        t = c.get('t')
        v = c.find('m:v', ns)
        is_ = c.find('m:is', ns)
        if is_ is not None:
            txt = ''.join(x.text or '' for x in is_.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            vals.append(txt)
        elif v is not None:
            vals.append(v.text)
        else:
            vals.append('')
    print(row.get('r'), '|', ' | '.join(vals))
"

